#include <iostream>
#include <iterator>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    std::ostream_iterator<int> outputIter(std::cout, " ");  // Creates an iterator tied to std::cout with a space delimiter
    std::copy(numbers.begin(), numbers.end(), outputIter);  // Uses the iterator to output elements
    std::cout << std::endl;  // Flushes the stream
    return 0;
}
